{"implementation": "def solve(case):
    nodes = case["nodes"]
    required_symbols = case["required_symbols"]

    # Validate required fields
    if "nodes" not in case:
        raise ValueError("Missing 'nodes' field")
    if "required_symbols" not in case:
        raise ValueError("Missing 'required_symbols' field")
    for node in nodes:
        for field in ["id", "parent", "symbol", "depth", "removable", "utility"]:
            if field not in node:
                raise ValueError(f"Node missing required field: {field}")

    required_symbols_set = set(required_symbols)

    # Build node lookup and children map
    node_by_id = {n["id"]: n for n in nodes}
    children = {n["id"]: [] for n in nodes}
    root_id = None

    for node in nodes:
        if node["parent"] is None:
            if root_id is not None:
                raise ValueError("Multiple root nodes found")
            root_id = node["id"]
        else:
            if node["parent"] not in node_by_id:
                raise ValueError(f"Parent '{node['parent']}' not found for node '{node['id']}'")
            children[node["parent"]].append(node["id"])

    if root_id is None:
        raise ValueError("No root node found")

    # Sort: deeper nodes first, stable tie-break by node ID (string sort)
    sorted_nodes = sorted(nodes, key=lambda n: (-n["depth"], n["id"]))

    retained = {n["id"] for n in nodes}
    removal_order = []

    for node in sorted_nodes:
        nid = node["id"]

        # Skip if not removable
        if not node["removable"]:
            continue

        # Skip if node's symbol is in required_symbols
        if node["symbol"] in required_symbols_set:
            continue

        # Skip if any children are still retained
        if any(c in retained for c in children[nid]):
            continue

        # Tentatively remove: check all required symbols still represented
        candidate_retained = retained - {nid}
        symbols_present = {node_by_id[i]["symbol"] for i in candidate_retained}

        if required_symbols_set.issubset(symbols_present):
            retained = candidate_retained
            removal_order.append(nid)

    return {
        "removed_node_ids": removal_order,
        "retained_node_ids": sorted(retained)
    }
"}
